    string Filial = "";
    if (authUser.Filial != null)
    {
        Filial = authUser.Filial;
    }
    var tokenDescriptor = new SecurityTokenDescriptor
    {
        Subject = new ClaimsIdentity(new[]
                {
                    new Claim(ClaimTypes.Name, authUser.Name),
                     new Claim("userNum", authUser.Id.ToString()),
                     new Claim("Filial",Filial),
                     new Claim("isFilialManager", authUser.IsFilialManager.ToString()),
                     new Claim("IsClientManager", authUser.IsClientManager.ToString()),
                     new Claim("Client", Client),
                     new Claim("IsSystemManager", authUser.IsSystemManager.ToString()),
                     new Claim("MainUserId", authUser.MainUserId.ToString()),
                     new Claim("CompanyName", authUser.CompanyName),
                     new Claim("ManageHimself", authUser.ManageHimself.ToString())
                }),

        Expires = now.AddMinutes(Convert.ToInt32(expireMinutes)),

        SigningCredentials = new SigningCredentials(new SymmetricSecurityKey(symmetricKey), SecurityAlgorithms.HmacSha256Signature)
    };

    var stoken = tokenHandler.CreateToken(tokenDescriptor);
    var token = tokenHandler.WriteToken(stoken);

    return token;
}

